#include<bits/stdc++.h>

using namespace std;
#define MAXP 1000005

vector<long long> prime_list;
void construct_plist(){
  vector<bool> fl(MAXP,false);
  for(int i=2;i<MAXP;i++){
    if(fl[i]){continue;}
    prime_list.push_back(i);
    for(int j=i;j<MAXP;j+=i){fl[j]=true;}
  }
}

long long f(long long p,long long q){
  double est=1;
  est=(q*q*q);
  est*=p;
  if(est>4e18){return 4e18;}
  return p*q*q*q;
}

int main(){
  construct_plist();
  long long n;
  cin >> n;
  long long res=0;
  int sz=prime_list.size();
  int q=sz-1;
  for(int p=0;p<sz;p++){
    while(p<q && f(prime_list[p],prime_list[q])>n){q--;}
    if(p>=q){break;}
    res+=(q-p);
  }
  cout << res << '\n';
  return 0;
}

#include<algorithm>
#include<cmath>
#include<iostream>
#include<vector>
/**
max以下の素数を昇順に列挙します。
計算量はO(max)です。
制約: 0≦max≦10^9
*/
std::vector<int> getPrimes(int max) {
  std::vector<int> primes;
  std::vector<int> lpf(max + 1, 0);
  for (int i = 2;i <= max;++ i) {
    if (lpf[i] == 0) {
      lpf[i] = i;
      primes.push_back(i);
    }
    for (int p : primes) {
      int mul = p * i;
      if (mul > max || p > lpf[i]) break; // ベルトラン＝チェビシェフの定理より、p*iはmaxの2倍以下
      lpf[mul] = p;
    }
  }
  return primes;
}

int main() {
  long long N;
  std::cin >> N;
  int cbrtN = std::cbrt(N);
  std::vector<int> primes = getPrimes(cbrtN);
  std::vector<int> cumsum(1, 0); // cumsum[i]はi以下の素数の個数を持つ
  cumsum.reserve(cbrtN + 1);
  for (int i = 1, pi = 0, p = 2;i <= cbrtN;++ i) {
    int last = cumsum[cumsum.size() - 1];
    if (i == p) {
      ++ last;
      ++ pi;
      p = pi >= (int)primes.size() ? cbrtN + 1 : primes[pi];
    }
    cumsum.push_back(last);
  }
  long long ans = 0;
  for (int q : primes) {
    int pMax = (int)std::min(q - 1LL, N / q / q / q);
    ans += cumsum[pMax];
  }
  std::cout << ans << std::endl;
}
